import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ code for a naive grouped transposed convolution
transposed_conv2d_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Naive grouped transposed convolution kernel
__global__ void transposed_conv2d_naive_kernel(
    const float* input,       // [N, C_in, H_in, W_in]
    const float* weight,      // [C_in, C_out_per_group, KH, KW]
    const float* bias,        // [C_out] or null if no bias
    float* output,            // [N, C_out, H_out, W_out]
    int N, int C_in, int H_in, int W_in,
    int C_out, int groups,
    int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int H_out, int W_out,
    bool has_bias)
{
    // Total threads = N*C_out*H_out*W_out
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * H_out * W_out;
    if (index >= total) return;

    // Decompose linear index
    int w_out = index % W_out;
    int tmp = index / W_out;
    int h_out = tmp % H_out;
    tmp /= H_out;
    int c_out = tmp % C_out;
    int n = tmp / C_out;

    // Which group are we in?
    int group_id = c_out / (C_out / groups);

    float val = 0.0f;
    // If there's a bias, initialize with bias
    if (has_bias) {
        val = bias[c_out];
    }

    // We want to find all (c_in, kh, kw) that contribute
    // output(n, c_out, h_out, w_out) = sum of input(n, c_in, h_in, w_in) * weight(...)
    // for each valid c_in that belongs to the same group
    // Decompose c_out to figure out the relevant c_in range
    int c_in_start = group_id * (C_in / groups);
    int c_in_end = c_in_start + (C_in / groups);

    for (int c_in_i = c_in_start; c_in_i < c_in_end; ++c_in_i) {
        for (int kh = 0; kh < KH; ++kh) {
            // Let's find the corresponding input height index
            // Transposed conv formula for output height:
            // out_h = (in_h - 1) * stride_h - 2*pad_h + dil_h*(KH-1) + 1
            // We invert it to find in_h that contributes to out_h
            // out_h + pad_h - kh*dil_h must be divisible by stride_h
            int in_h = h_out + pad_h - kh * dil_h;
            if (in_h % stride_h != 0) { 
                continue; 
            }
            in_h /= stride_h;
            if (in_h < 0 || in_h >= H_in) {
                continue;
            }

            for (int kw_ = 0; kw_ < KW; ++kw_) {
                int in_w = w_out + pad_w - kw_ * dil_w;
                if (in_w % stride_w != 0) {
                    continue;
                }
                in_w /= stride_w;
                if (in_w < 0 || in_w >= W_in) {
                    continue;
                }

                // weight offset: weight[c_in_i, c_out_per_group, kh, kw_]
                // c_out_per_group = c_out % (C_out / groups) for the group
                int c_out_per_group = c_out - group_id * (C_out / groups);

                // input index:
                // input_offset = n*C_in*H_in*W_in + c_in_i*H_in*W_in + in_h*W_in + in_w
                int input_offset = ((n * C_in + c_in_i) * H_in + in_h) * W_in + in_w;
                // weight offset:
                // weight_offset = c_in_i*(C_out/groups)*KH*KW (but c_in_i is global, so we need local within group)
                // The local c_in within the group is c_in_i - c_in_start
                int local_c_in = c_in_i - c_in_start;
                int weight_offset = (((local_c_in) * (C_out / groups) + c_out_per_group) * KH + kh) * KW + kw_;

                val += input[input_offset] * weight[weight_offset];
            }
        }
    }

    // Write result
    // output_offset = n*C_out*H_out*W_out + c_out*H_out*W_out + h_out*W_out + w_out
    int output_offset = ((n * C_out + c_out) * H_out + h_out) * W_out + w_out;
    output[output_offset] = val;
}

torch::Tensor transposed_conv2d_cuda(
    torch::Tensor input,    // [N, C_in, H_in, W_in]
    torch::Tensor weight,   // [C_in, C_out_per_group, KH, KW]
    torch::Tensor bias,     // [C_out] (may be empty if no bias)
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups)
{
    auto in_sizes = input.sizes();
    int N = in_sizes[0];
    int C_in = in_sizes[1];
    int H_in = in_sizes[2];
    int W_in = in_sizes[3];

    auto w_sizes = weight.sizes();
    // w_sizes: [C_in, C_out_per_group, KH, KW]
    int KH = w_sizes[2];
    int KW = w_sizes[3];
    int C_out = (w_sizes[1] * groups); // total out channels = out_per_group * groups

    // Compute output height/width for transposed conv
    // H_out = (H_in - 1)*stride_h - 2*pad_h + dil_h*(KH - 1) + 1
    // W_out = (W_in - 1)*stride_w - 2*pad_w + dil_w*(KW - 1) + 1
    int H_out = (H_in - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + 1;
    int W_out = (W_in - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + 1;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({N, C_out, H_out, W_out}, options);

    bool has_bias = (bias.numel() != 0);

    int total_threads = N * C_out * H_out * W_out;
    int block_size = 256;
    int grid_size = (total_threads + block_size - 1) / block_size;

    transposed_conv2d_naive_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N, C_in, H_in, W_in, C_out, groups,
        KH, KW, stride_h, stride_w,
        pad_h, pad_w, dil_h, dil_w,
        H_out, W_out,
        has_bias
    );

    return output;
}
''';

transposed_conv2d_cpp_source = r'''
torch::Tensor transposed_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups);
''';

# Build the inline extension
transposed_conv2d_mod = load_inline(
    name="transposed_conv2d_mod",
    cpp_sources=transposed_conv2d_cpp_source,
    cuda_sources=transposed_conv2d_source,
    functions=["transposed_conv2d_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    A custom transposed convolution implementation using a naive CUDA kernel.
    Mirrors nn.ConvTranspose2d with grouping, dilation, etc.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1),
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()
        # We'll store weights/bias as nn.Parameters to learn them.
        # Weight shape for ConvTranspose2d: [in_channels, out_channels/groups, kernel_h, kernel_w]
        kernel_h, kernel_w = kernel_size
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        # out_channels_per_group
        out_channels_per_group = out_channels // groups

        weight = torch.empty(
            in_channels,
            out_channels_per_group,
            kernel_h,
            kernel_w,
            dtype=torch.float32
        )
        # kaiming init or something similar
        nn.init.kaiming_uniform_(weight, a=5**0.5)
        self.weight = nn.Parameter(weight)

        if bias:
            b = torch.zeros(out_channels, dtype=torch.float32)
            self.bias = nn.Parameter(b)
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # x shape: [N, in_channels, H_in, W_in]
        stride_h, stride_w = self.stride
        pad_h, pad_w = self.padding
        dil_h, dil_w = self.dilation

        if self.has_bias:
            return transposed_conv2d_mod.transposed_conv2d_cuda(
                x,
                self.weight,
                self.bias,
                stride_h, stride_w,
                pad_h, pad_w,
                dil_h, dil_w,
                self.groups
            )
        else:
            # Pass empty tensor for bias
            empty_bias = torch.tensor([], device=x.device, dtype=x.dtype)
            return transposed_conv2d_mod.transposed_conv2d_cuda(
                x,
                self.weight,
                empty_bias,
                stride_h, stride_w,
                pad_h, pad_w,
                dil_h, dil_w,
                self.groups
            )
